// SPDX-License-Identifier: GPL-3.0-only
// Boot screen record for the installer page. The bytes match firmware/src/app/boot_screen.h.
// A save is not done until the keyboard's END reply is 0. Anything refused leaves the previous screen.
import { pack78, unpack78, slotReq } from "./x0x_breaks.js";

export const BOOT_LINE0 = 12, BOOT_LINE1 = 21, BOOT_W = 240, BOOT_H = 96;
export const BOOT_PIC_BYTES = (BOOT_W * BOOT_H) / 8;
export const BOOT_FIXED = 44;
export const BOOT_FILE_MAX = 8 * 1024 * 1024;
const KIND_CUSTOM = 1, KIND_FACTORY = 2, F_PIC = 1;
const CMD = { info: 39, begin: 43, write: 44, read: 45, end: 46, abort: 47 };

function bad(code) { return { ok: false, code }; }

function lineBytes(s, max) {
  const t = String(s ?? "");
  if (t.length > max) return null;
  const out = new Uint8Array(max);
  for (let i = 0; i < t.length; i++) {
    const c = t.charCodeAt(i);
    if (c < 32 || c > 126) return null;
    out[i] = c;
  }
  return { n: t.length, bytes: out };
}

// {ok, bytes} or {ok:false, code}. codes: short, long0, long1, chars, picsize.
export function bootPack({ factory = false, line0 = "", line1 = "", bits = null } = {}) {
  if (factory) {
    const rec = new Uint8Array(BOOT_FIXED);
    rec[0] = KIND_FACTORY;
    return { ok: true, bytes: rec };
  }
  if (!String(line0).length || !String(line1).length) return bad("short");
  if (String(line0).length > BOOT_LINE0) return bad("long0");
  if (String(line1).length > BOOT_LINE1) return bad("long1");
  const a = lineBytes(line0, BOOT_LINE0), b = lineBytes(line1, BOOT_LINE1);
  if (!a || !b) return bad("chars");
  if (!a.n || !b.n) return bad("short");
  const pic = bits != null;
  if (pic && bits.length !== BOOT_PIC_BYTES) return bad("picsize");
  const rec = new Uint8Array(BOOT_FIXED + (pic ? BOOT_PIC_BYTES : 0));
  rec[0] = KIND_CUSTOM;
  rec[1] = pic ? F_PIC : 0;
  rec[2] = a.n;
  rec[3] = b.n;
  rec.set(a.bytes, 4);
  rec.set(b.bytes, 16);
  if (pic) {
    rec[40] = BOOT_W & 255;
    rec[41] = BOOT_W >> 8;
    rec[42] = BOOT_H & 255;
    rec[43] = BOOT_H >> 8;
    rec.set(bits, BOOT_FIXED);
  }
  return { ok: true, bytes: rec };
}

// 240×96 RGBA (straight alpha) -> 1-bit, amber ink on black. null if the buffer is the wrong size.
export function bootRgbaToBits(rgba) {
  if (!rgba || rgba.length !== BOOT_W * BOOT_H * 4) return null;
  const bits = new Uint8Array(BOOT_PIC_BYTES), stride = BOOT_W / 8;
  for (let y = 0; y < BOOT_H; y++) {
    for (let x = 0; x < BOOT_W; x++) {
      const i = (y * BOOT_W + x) * 4;
      const lum = rgba[i] * 0.299 + rgba[i + 1] * 0.587 + rgba[i + 2] * 0.114;
      if (rgba[i + 3] >= 128 && lum >= 128)
        bits[y * stride + (x >> 3)] |= 0x80 >> (x & 7);
    }
  }
  return bits;
}

export function bootBitsToRgba(bits) {
  const rgba = new Uint8ClampedArray(BOOT_W * BOOT_H * 4);
  if (!bits || bits.length !== BOOT_PIC_BYTES) return rgba;
  const stride = BOOT_W / 8;
  for (let y = 0; y < BOOT_H; y++) {
    for (let x = 0; x < BOOT_W; x++) {
      const on = bits[y * stride + (x >> 3)] & (0x80 >> (x & 7));
      const i = (y * BOOT_W + x) * 4;
      if (on) { rgba[i] = 232; rgba[i + 1] = 136; rgba[i + 2] = 30; }
      rgba[i + 3] = 255;
    }
  }
  return rgba;
}

function textFrom(bytes, max) {
  let s = "";
  for (let i = 0; i < bytes.length && i < max && bytes[i]; i++) s += String.fromCharCode(bytes[i]);
  return s;
}

// Device reply after the command byte. Does not claim success unless END is 0.
export async function bootTransfer(link, bytes) {
  let began = false, ended = false;
  const abort = async () => {
    try { await slotReq(link, CMD.abort, [], 1000, 1); } catch (_) { /* the stage also times out */ }
  };
  try {
    let r = await slotReq(link, CMD.begin, [], 5000);
    if (!r.length || r[0]) return { ok: false, code: r[0] || 1, ended: false };
    began = true;
    for (let off = 0; off < bytes.length; off += 256) {
      const chunk = bytes.subarray(off, Math.min(bytes.length, off + 256));
      r = await slotReq(link, CMD.write, [off & 127, (off >> 7) & 127, (off >> 14) & 127, ...pack78(chunk)]);
      if (r.length < 4 || r[3]) {
        await abort();
        return { ok: false, code: r.length >= 4 ? r[3] : 1, ended: false };
      }
    }
    ended = true;
    r = await slotReq(link, CMD.end, [], 15000);
    if (!r.length || r[0]) return { ok: false, code: r[0] || 1, ended: true };
    return { ok: true, ended: true };
  } catch (e) {
    if (began && !ended) await abort();
    return { ok: false, code: ended ? "unconfirmed" : "lost", ended, error: e };
  }
}

export async function bootRead(link) {
  const r = await slotReq(link, CMD.info, [], 3000);
  if (!r.length) throw new Error("short");
  let i = 2;
  const take = () => {
    let s = "";
    while (i < r.length && r[i]) s += String.fromCharCode(r[i++]);
    i++;
    return s;
  };
  const status = r[0], flags = r[1] || 0;
  const line0 = take(), line1 = take();
  let bits = null;
  if (status !== 2 && flags & F_PIC) {
    bits = new Uint8Array(BOOT_PIC_BYTES);
    for (let off = 0; off < BOOT_PIC_BYTES;) {
      const want = Math.min(224, BOOT_PIC_BYTES - off), adr = BOOT_FIXED + off;
      const part = await slotReq(link, CMD.read, [adr & 127, (adr >> 7) & 127, (adr >> 14) & 127, (want + 1) >> 1]);
      if (!part.length || part[0]) throw new Error("read");
      const raw = unpack78(part.slice(4));
      const n = Math.min(raw.length, BOOT_PIC_BYTES - off);
      bits.set(raw.subarray(0, n), off);
      off += n;
      if (!n) throw new Error("read");
    }
  }
  return { status, line0, line1, bits };
}

/* SPDX-License-Identifier: GPL-3.0-only */
/* X0X master section, after the send FX: compressor (with kick-keyed PUMP), resonant
 * filter, volume, limiter. See master.c. */
#pragma once
#include <stdint.h>
#include "x0x_param.h"

enum {
    MST_THRESH, MST_RATIO, MST_ATTACK, MST_RELEASE,     /* page COMP */
    MST_MAKEUP, MST_MIX, MST_PUMP, MST_PUMPSRC,         /* page COMP 2 */
    MST_MODE, MST_CUTOFF, MST_RESO, MST_LIMIT,          /* page FILTER (+ the limiter switch) */
    MST_COMP1, MST_DJF,                                 /* X0X: one-knob COMP and FILTER (set the pots above) */
    MST_NPARAMS
};
enum { PUMP_909, PUMP_808, PUMP_BOTH };

typedef struct {
    uint8_t pot[MST_NPARAMS];
    /* compressor */
    float thr_db, slope, knee;        /* static curve: slope = 1 - 1/ratio; knee width, dB */
    float a_att, a_rel;               /* one-pole coefficients of the gain-reduction smoother */
    float makeup, mix;                /* linear makeup gain, wet share */
    float gr;                         /* smoothed gain reduction, dB (>= 0) */
    float ms, a_det;                  /* the level it reads: mean square over ~8 ms (not each sample) */
    float want;                       /* the static curve's reduction, dB: read every MST_CR samples */
    float g_lin, g_step;              /* makeup x the reduction, linear: set every MST_CR samples, ramped */
    uint8_t cr;                       /* samples to the next control-rate update */
#define MST_CR 4
    float pump_db, pump, pump_tgt;    /* PUMP depth; its envelope (dB) and the target it rises to */
    float a_pump;                     /* PUMP rise: MASTER_PUMP_RISE_MS */
    uint8_t comp_on;                  /* ratio > 1:1 or PUMP: else bypassed, sample for sample */
    float gr_view;                    /* gain reduction for the screen, dB, peak-held */
    /* filter */
    float g, g_t, k;
    float a1;                         /* 1 / (1 + g (g + k)): recomputed only while g moves */
    float ic1, ic2;
    float ic1r, ic2r;                 /* X0X stereo: the right side's filter state */
    float vol_cur;                    /* X0X: master_process_st's volume, gliding to the knob (< 0: unset) */
    /* limiter: looks MST_LA samples ahead, so it can lower the gain before a peak arrives */
#define MST_LA 64
    float env, gain, inv_env;         /* inv_env = 1 / env, kept up as env moves (no divide a sample) */
    float la[MST_LA], la_r[MST_LA];
    int la_pos, hold;
} master_t;

/* the one-knob macros' pots: COMP 0 = off .. 127 (THRESH, RATIO, MAKEUP); FILTER 64 = off, under it a
 * low-pass sweeping down, over it a high-pass sweeping up (MODE, CUTOFF). The UI writes the same pots
 * into its mirror, so the details it lists are what plays */
void master_comp1_pots(int v, uint8_t *thresh, uint8_t *ratio, uint8_t *makeup);
void master_djf_pots(int v, uint8_t *mode, uint8_t *cutoff);

void master_init(master_t *m);
int master_nparams(void);
const x0x_param_t *master_param(int i);
void master_set(master_t *m, int i, int value);
int master_get(const master_t *m, int i);
/* a kick was triggered (kit 0 = 909, 1 = 808; vel 0..1): the PUMP's key */
void master_key(master_t *m, int kit, float vel);
/* in place, mono: compressor, filter, volume (0..1+), limiter */
void master_process(master_t *m, float *x, int n, float volume);
/* X0X stereo: the compressor reads both sides' power, the limiter the louder side, and each moves
 * both together; the filter runs on each. With l == r it is master_process exactly. */
void master_process_st(master_t *m, float *l, float *r, int n, float volume);
/* the value of a pot in its unit, for the screen ("-12 dB", "4:1", "30 ms") */
void master_format(const master_t *m, int i, char *buf);

/* SPDX-License-Identifier: GPL-3.0-only
 * Native link-level regression for MID-13: queued MIDI transport versus
 * an INTERNAL clock-source edit in the same audio block.
 * Compile with production sequencer.c + pattern.c + tb3po.c.
 * Never claim that this is real hardware timing or firmware package QA.
 */
#include <stdio.h>
#include <stdlib.h>
#include "sequencer.h"

static pattern_t patterns[NPAT];
static int checks, failures;
static unsigned frames = 1u;
#define CHECK(expr) do { ++checks; if (!(expr)) { ++failures; fprintf(stderr, "FAIL %s:%d: %s\n", __FILE__, __LINE__, #expr); } } while (0)

static void start(seq_t *s)
{
    static int initialized;
    if (!initialized) {
        for (int i = 0; i < NPAT; ++i)
            pattern_init(&patterns[i], (unsigned)(123 + i), (unsigned)(789 + i));
        initialized = 1;
    }
    seq_init(s, patterns);
    s->send_clock = 0;
}

static void settle(seq_t *s)
{
    seq_sink_t out = {0};
    seq_advance(s, frames, &out);
}

static void remote_start_cancel(int clock, int msg)
{
    seq_t s;
    start(&s);
    s.clk_src = (unsigned char)clock;
    settle(&s); /* apply EXTERNAL or AUTO before the remote transport */
    CHECK(seq_midi_rt(&s, (unsigned char)msg) == 1);
    CHECK(s.req_start || s.req_cont);
    s.clk_src = SEQ_CLK_INT;
    settle(&s);
    CHECK(s.clk_cur == SEQ_CLK_INT);
    CHECK(!s.playing);
    CHECK(!s.req_start && !s.req_cont && !s.req_rt);
    CHECK(s.ext_pending == 0);
}

static void remote_stop_cancel(int clock)
{
    seq_t s;
    start(&s);
    s.clk_src = (unsigned char)clock;
    settle(&s);
    seq_start(&s); /* local PLAY, should survive the clock-source edit */
    settle(&s);
    CHECK(s.playing);
    CHECK(seq_midi_rt(&s, 0xFCu) == 1); /* incoming remote STOP, still queued */
    CHECK(s.req_stop);
    s.clk_src = SEQ_CLK_INT;
    settle(&s);
    CHECK(s.clk_cur == SEQ_CLK_INT);
    CHECK(s.playing);
    CHECK(!s.req_stop);
}

static void local_transport_survives(int clock)
{
    seq_t s;
    start(&s);
    s.clk_src = (unsigned char)clock;
    settle(&s);
    seq_start(&s);                  /* local PLAY immediately before clock source change */
    s.clk_src = SEQ_CLK_INT;
    settle(&s);
    CHECK(s.playing);
    CHECK(s.start_local);
    CHECK(!s.req_start);
    /* local STOP must still work while INTERNAL */
    seq_stop(&s);
    settle(&s);
    CHECK(!s.playing);
    CHECK(!s.req_stop);
}

static void already_playing_survives(int clock)
{
    seq_t s;
    start(&s);
    s.clk_src = (unsigned char)clock;
    settle(&s);
    seq_start(&s);
    settle(&s);
    CHECK(s.playing);
    s.clk_src = SEQ_CLK_INT;
    settle(&s);
    CHECK(s.playing);
    CHECK(!s.req_start && !s.req_cont && !s.req_stop);
    CHECK(seq_midi_rt(&s, 0x80u) == 0); /* NOTE OFF must not be eaten by transport */
}

static void immediate_internal_incoming_ignored(void)
{
    seq_t s;
    start(&s);
    s.clk_src = SEQ_CLK_INT;
    CHECK(seq_midi_rt(&s, 0xFAu) == 1);
    CHECK(seq_midi_rt(&s, 0xFBu) == 1);
    CHECK(seq_midi_rt(&s, 0xFCu) == 1);
    CHECK(seq_midi_rt(&s, 0xF8u) == 1);
    settle(&s);
    CHECK(!s.playing);
    CHECK(!s.req_start && !s.req_cont && !s.req_stop);
    CHECK(!s.ext_pending);
}

int main(void)
{
    static const unsigned block_frames[] = {1u, 64u, 1024u};
    for (unsigned block = 0; block < sizeof block_frames / sizeof block_frames[0]; ++block) {
        frames = block_frames[block];
        for (unsigned clock = SEQ_CLK_AUTO; clock <= SEQ_CLK_EXT; clock += 2) {
            remote_start_cancel(clock, 0xFAu);
            remote_start_cancel(clock, 0xFBu);
            remote_stop_cancel(clock);
            local_transport_survives(clock);
            already_playing_survives(clock);
        }
        immediate_internal_incoming_ignored();
    }
    fprintf(stderr, "MID-13 linked first-NIGHTLY clock change: %d/%d assertions %s\n",
            checks - failures, checks, failures ? "FAILED" : "PASSED");
    return failures ? EXIT_FAILURE : EXIT_SUCCESS;
}

/* SPDX-License-Identifier: GPL-3.0-only */
/* SMK-37: the chip side of the Bluetooth controller image (src/ble.c does the rest).
 *
 * The controller is a separate image in the flash block at 0x8B000 (XIP 0x02087000), built by the
 * user from JieLi's files (ble/ctl). The app never links it: it checks the image header and CRC,
 * gives it boot parameters and runs its two entries on core 1 (fm1_cpu1.h). Everything else goes
 * through the HCI mailbox (x0x_ble_abi.h). This file holds the addresses and the chip values that
 * src/ may not write as numbers (tools/build.py mmio_check). */
#pragma once
#include <stdint.h>
#define XB_SYNC() __asm__ volatile("csync" ::: "memory")
#include "x0x_ble_abi.h"

#define FM1_BLE_HDR ((const xb_header_t *)XB_FLASH_XIP)
#define FM1_BLE_IMG ((const uint8_t *)XB_FLASH_XIP)
#define FM1_BLE_INIT_MS 4000u                   /* the longest the controller's start may take (its RF
                                                 * trim; the watchdog is 8 s, fed just before) */

/* WLA_CON12: the 24 MHz crystal's trim, left bits 13-16, right bits 19-22. JieLi's RF init
 * (wf_rf_common_init) writes both fields from xb_boot_t xosc[]. */
#define FM1_BLE_XOSC_REG (*(volatile uint32_t *)0x11930u)
static inline uint32_t fm1_ble_xosc(void) { return FM1_BLE_XOSC_REG; }
static inline void fm1_ble_sync(void) { XB_SYNC(); }
/* the image's init entry, called on core 0 (it moves to the image's run stack itself) */
static inline int fm1_ble_init_here(uint32_t init, const xb_boot_t *b)
{
    return ((int (*)(const xb_boot_t *))(uintptr_t)init)(b);
}   /* the two cores share the caches: order only */

/* The boot parameters. Clocks as measured on an FM-1 (docs/plans/2026-10-04-dual-core-and-clock.md:
 * system 360 MHz, HSB 180, LSB 60). RF calibration: the AC79 SDK's demo_ble board values (the unit's
 * own are not known: Stage 3 checks the link). */
static void fm1_ble_boot_fill(xb_boot_t *b, xb_mbox_t *mb)
{
    static const uint8_t pa[7] = {1, 7, 4, 7, 11, 1, 7};
    uint32_t i;
    uint8_t *z = (uint8_t *)b;
    for (i = 0; i < sizeof *b; i++)
        z[i] = 0;
    b->magic = XB_BOOT_MAGIC;
    b->abi = XB_ABI;
    b->sys_clk_hz = 360000000u;
    b->hsb_clk_hz = 180000000u;
    b->lsb_clk_hz = 60000000u;
    b->tick_addr = 0x10804u;                    /* TIMER4: free-running, 24 MHz (fm1_time.h) */
    b->ticks_per_ms = 24000u;
    b->mbox = (uint32_t)(uintptr_t)mb;
    b->settle_ms = 800u;
    b->vec_base = 0x01C7FE00u;                  /* FM1_VEC: one table for both cores */
    b->icfg_base = 0x1EEF300u;                  /* core 1's interrupt bank */
    /* a67: a fixed crystal trim 11/11, as the working SMK-37 Oscuro firmware (and the SDK default).
     * Before a67 the trim came from WLA_CON12 at boot (3/3 on the user's unit). DIAG still reads WLA_CON12. */
    b->xosc[0] = 0x0B;
    b->xosc[1] = 0x0B;
    for (i = 0; i < 7u; i++)
        b->pa_trim[i] = pa[i];
    b->osc_type = 0;
    b->pwr_max = 8;
    b->pwr_ble = 6;                             /* BLE TX level (0-11). a66: 6, as the working SMK-37 Oscuro firmware (was 11) */
}

#!/usr/bin/env python3
# SPDX-License-Identifier: GPL-3.0-only
"""Compile the actual native pending query against volatile ring indices."""
import os, re, subprocess, tempfile
from pathlib import Path
root=Path(__file__).resolve().parents[2]
src=(root/'firmware/src/app/plat_fm1.c').read_text()
matches=[re.search(pattern,src) for pattern in [r'int plat_midi_pending\(void\)\s*\{[^}]*\}',r'uint32_t plat_midi_mark\(void\)\s*\{[^}]*\}',r'int plat_midi_passed\(uint32_t mark\)\s*\{[^}]*\}']]
assert all(matches), 'actual native query/watermark missing'
probe='''#include <stdint.h>
#include <assert.h>
#include <stdio.h>
static volatile uint32_t mi_r,mi_w;
'''+ '\n'.join(m.group() for m in matches)+'''
int main(void){
 const uint32_t cases[][2]={{0,0},{0,1},{63,64},{64,64},{UINT32_MAX,0},{UINT32_MAX,UINT32_MAX}};
 for(unsigned k=0;k<sizeof cases/sizeof cases[0];k++){
  mi_r=cases[k][0];mi_w=cases[k][1];
  assert(plat_midi_pending()==(cases[k][0]!=cases[k][1]));
  assert(plat_midi_mark()==cases[k][1]);
  assert(plat_midi_passed(cases[k][0]));
  assert(mi_r==cases[k][0] && mi_w==cases[k][1]);
 }
 mi_r=0;mi_w=1;assert(!plat_midi_passed(1));assert(plat_midi_passed(UINT32_MAX));
 mi_r=UINT32_MAX;mi_w=0;assert(!plat_midi_passed(0));
 mi_r=1;assert(plat_midi_passed(0));
 puts("PASS actual native non-consuming pending query: empty, pending, ring/writer counter wrap; no native firmware build claim");
}
'''
with tempfile.TemporaryDirectory() as tmp:
 p=Path(tmp);(p/'probe.c').write_text(probe)
 subprocess.run([os.environ.get('CC','cc'),'-std=c99','-Wall','-Wextra','-Werror',str(p/'probe.c'),'-o',str(p/'probe')],check=True)
 subprocess.run([str(p/'probe')],check=True)

#!/usr/bin/env python3
"""Fail-closed, SHA-pinned source checkout via GitHub's Git Data REST API.

Uses a local Git object cache when supplied. Never calls GitHub Actions,
changes remote refs, publishes binaries, or flashes hardware. A checkout is
usable for development builds, NOT by itself a qualified firmware candidate.
"""
from __future__ import annotations

import argparse
import base64
import binascii
import calendar
import hashlib
import ipaddress
import json
import os
import posixpath
from pathlib import Path
import re
import shutil
import subprocess
import tempfile
import time
from urllib.error import HTTPError, URLError
from urllib.parse import quote, urlsplit
from urllib.request import Request, urlopen

HEX = re.compile(r'^[0-9a-f]{40}$')
REPO = re.compile(r'^[A-Za-z0-9_.-]+/[A-Za-z0-9_.-]+$')
MODES = {'100644', '100755', '120000'}


def git(path: Path, *args: str, data: bytes | None = None) -> str:
    p = subprocess.run(['git', '-C', str(path), *args], input=data,
                       stdout=subprocess.PIPE, stderr=subprocess.PIPE, check=False)
    if p.returncode:
        raise RuntimeError(f'git {" ".join(args)}: {p.stderr.decode(errors="replace").strip()}')
    return p.stdout.decode('utf-8').strip()


def object_hash(kind: str, data: bytes) -> str:
    return hashlib.sha1(f'{kind} {len(data)}\0'.encode() + data).hexdigest()


def api_base(url: str) -> str:
    u = urlsplit(url.rstrip('/'))
    allowed_local = u.scheme == 'http' and u.hostname in ('localhost', '127.0.0.1', '::1')
    if u.scheme != 'https' and not allowed_local:
        raise ValueError('GitHub API transport must use HTTPS (except loopback tests)')
    if u.hostname not in ('api.github.com', 'localhost', '127.0.0.1', '::1'):
        raise ValueError('Refusing to transmit GitHub API credentials to an untrusted host')
    if not u.netloc or u.username or u.password or u.query or u.fragment or u.path not in ('', '/'):
        raise ValueError('Invalid GitHub API base URL')
    return url.rstrip('/')


class API:
    def __init__(self, base: str, token: str | None = None):
        self.base = api_base(base)
        self.token = token
        self.read_count = 0

    def get(self, path: str) -> dict:
        if not path.startswith('/repos/') or '..' in path or '//' in path:
            raise ValueError('Unsafe GitHub REST path')
        headers = {'Accept': 'application/vnd.github+json',
                   'X-GitHub-Api-Version': '2022-11-28', 'User-Agent': 'x0x37-git-api-checkout/1'}
        if self.token:
            headers['Authorization'] = 'Bearer ' + self.token
        for attempt in range(3):
            try:
                with urlopen(Request(self.base + path, headers=headers), timeout=35) as res:
                    if urlsplit(res.geturl()).hostname != urlsplit(self.base).hostname:
                        raise ValueError('GitHub API redirected to an unexpected host')
                    raw = res.read(8 * 1024 * 1024 + 1)
                    if len(raw) > 8 * 1024 * 1024:
                        raise ValueError('GitHub API object too large')
                self.read_count += 1
                value = json.loads(raw)
                if not isinstance(value, dict):
                    raise ValueError('Unexpected GitHub API JSON object')
                return value
            except HTTPError as exc:
                if exc.code not in (429, 500, 502, 503, 504) or attempt == 2:
                    raise RuntimeError(f'GitHub API GET {path} failed HTTP {exc.code}') from exc
            except URLError as exc:
                if attempt == 2:
                    raise RuntimeError(f'GitHub API GET {path} failed: {exc.reason}') from exc
            time.sleep(0.25 * (2 ** attempt))
        raise AssertionError('Unreachable retry state')


def _tz_candidates():
    # The REST API reports UTC while raw unsigned Git objects preserve local TZ.
    yield '+0000'
    for minute in range(-14 * 60, 14 * 60 + 1, 15):
        if minute:
            yield ('+' if minute >= 0 else '-') + f'{abs(minute)//60:02d}{abs(minute)%60:02d}'


def exact_commit_bytes(commit: dict, wanted: str) -> bytes:
    verification = commit.get('verification') or {}
    payload = verification.get('payload')
    signature = verification.get('signature')
    if payload is not None:
        if not isinstance(payload, str) or '\n\n' not in payload:
            raise ValueError('Malformed signed/verified commit payload')
        raw = payload
        if signature is not None:
            if not isinstance(signature, str) or not signature.endswith('\n'):
                raise ValueError('Malformed GitHub commit signature')
            raw = raw.replace('\n\n', '\ngpgsig ' + signature.replace('\n', '\n ') + '\n\n', 1)
        result = raw.encode('utf-8')
        if object_hash('commit', result) != wanted:
            raise ValueError('GitHub commit payload/signature does not recreate expected SHA')
        return result
    tree = commit.get('tree', {}).get('sha')
    parents = [p.get('sha') for p in commit.get('parents', [])]
    if not isinstance(tree, str) or not HEX.fullmatch(tree) or any(not isinstance(p, str) or not HEX.fullmatch(p) for p in parents):
        raise ValueError('Commit tree/parents are invalid')
    # For old unsigned Git commits, try Git's standard timezone offsets and
    # verify the exact commit object SHA. Never accept an inferred unmatched SHA.
    persons = []
    for role in ('author', 'committer'):
        item = commit[role]
        name, email, utc = item['name'], item['email'], item['date']
        if any(c in name + email for c in '\r\n<>'):
            raise ValueError('Unsupported commit identity')
        timestamp = calendar.timegm(time.strptime(utc, '%Y-%m-%dT%H:%M:%SZ'))
        persons.append((role, name, email, timestamp))
    prefix = f'tree {tree}\n' + ''.join(f'parent {p}\n' for p in parents)
    if not isinstance(commit.get('message'), str):
        raise ValueError('Commit message missing')
    suffix = '\n\n' + commit['message']
    for a in _tz_candidates():
        for c in _tz_candidates():
            pa, pc = persons
            raw = (prefix + f'author {pa[1]} <{pa[2]}> {pa[3]} {a}\n'
                   + f'committer {pc[1]} <{pc[2]}> {pc[3]} {c}' + suffix).encode()
            if object_hash('commit', raw) == wanted:
                return raw
    raise ValueError('Cannot reconstruct original unsigned commit object exactly')


def validated_entries(tree: dict, expected_sha: str) -> list[dict]:
    if tree.get('truncated') is not False or tree.get('sha') != expected_sha:
        raise ValueError('Incomplete/mismatched GitHub tree; refusing checkout')
    entries = []
    seen = set()
    for item in tree.get('tree', []):
        if not isinstance(item, dict):
            raise ValueError('Invalid tree entry')
        if item.get('type') == 'tree':
            continue
        name, mode, sha = item.get('path'), item.get('mode'), item.get('sha')
        if (not isinstance(name, str) or not name or name.startswith('/')
                or any(x in ('', '.', '..', '.git') for x in name.split('/'))
                or any(c in name for c in '\x00\r\n\\') or name in seen
                or mode not in MODES or item.get('type') != 'blob'
                or not isinstance(sha, str) or not HEX.fullmatch(sha)
                or not isinstance(item.get('size'), int) or item['size'] < 0):
            raise ValueError(f'Unsupported/unsafe GitHub tree entry: {name!r}')
        seen.add(name)
        entries.append({'path': name, 'mode': mode, 'sha': sha, 'size': item['size']})
    if not entries:
        raise ValueError('Empty Git source tree')
    return entries


def fetch_missing(api: API, repo: str, source: Path, entries: list[dict]) -> int:
    missing = {}
    for e in entries:
        if e['sha'] in missing:
            continue
        found = subprocess.run(['git', '-C', str(source), 'cat-file', '-e', e['sha'] + '^{blob}'],
                               stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL).returncode == 0
        if not found:
            missing[e['sha']] = e['size']
        elif int(git(source, 'cat-file', '-s', e['sha'])) != e['size']:
            raise ValueError('Cached Git blob size mismatch: ' + e['sha'])
    for sha, size in missing.items():
        blob = api.get(f'/repos/{repo}/git/blobs/{sha}')
        if blob.get('sha') != sha or blob.get('encoding') != 'base64':
            raise ValueError('Incorrect GitHub blob response SHA/encoding: ' + sha)
        try:
            content = base64.b64decode(''.join(blob['content'].split()), validate=True)
        except (ValueError, KeyError, binascii.Error) as exc:
            raise ValueError('Malformed GitHub blob base64: ' + sha) from exc
        if len(content) != size or blob.get('size') != size or object_hash('blob', content) != sha:
            raise ValueError('GitHub blob integrity mismatch: ' + sha)
        if git(source, 'hash-object', '-t', 'blob', '-w', '--stdin', data=content) != sha:
            raise ValueError('Imported Git blob differs from GitHub: ' + sha)
    # Keep Git symlinks strictly inside this exact source root. A checked-out
    # source must not let builds read local SDK/credentials through aliases.
    for entry in entries:
        if entry['mode'] == '120000':
            target = subprocess.check_output(['git', '-C', str(source), 'cat-file', 'blob', entry['sha']])
            if b'\x00' in target or b'\n' in target or b'\\' in target:
                raise ValueError('Unsafe Git symlink target: ' + entry['path'])
            relative = target.decode('utf-8')
            joined = posixpath.normpath(posixpath.join(posixpath.dirname(entry['path']), relative))
            if (relative.startswith('/') or joined == '..' or joined.startswith('../')
                    or joined == '.' or not relative):
                raise ValueError('Git symlink points outside source tree: ' + entry['path'])
    return len(missing)


def reconstruct(api: API, repo: str, commit_sha: str, expected_tree: str | None,
                output: Path, seed: Path | None, verify_ref: str | None) -> dict:
    if not REPO.fullmatch(repo) or not HEX.fullmatch(commit_sha):
        raise ValueError('Invalid owner/repository or immutable commit SHA')
    if expected_tree and not HEX.fullmatch(expected_tree):
        raise ValueError('Expected tree must be full lowercase 40-character SHA')
    if verify_ref and not re.fullmatch(r'[A-Za-z0-9][A-Za-z0-9_.\-/]*', verify_ref):
        raise ValueError('Invalid verification ref')
    endpoint = '/repos/' + repo
    if verify_ref:
        branch = api.get(endpoint + '/branches/' + quote(verify_ref, safe=''))
        if branch.get('commit', {}).get('sha') != commit_sha:
            raise ValueError('Remote verification branch moved or differs from pinned commit')
    commit = api.get(endpoint + '/git/commits/' + commit_sha)
    if commit.get('sha') != commit_sha:
        raise ValueError('GitHub commit identity mismatch')
    tree_sha = commit.get('tree', {}).get('sha')
    if not isinstance(tree_sha, str) or not HEX.fullmatch(tree_sha) or (expected_tree and tree_sha != expected_tree):
        raise ValueError('Unexpected commit tree SHA')
    raw_commit = exact_commit_bytes(commit, commit_sha)
    entries = validated_entries(api.get(endpoint + '/git/trees/' + tree_sha + '?recursive=1'), tree_sha)
    output = output.expanduser().absolute()
    if output.exists() or output.is_symlink():
        raise ValueError('Output already exists; refusing to overwrite')
    if not output.parent.is_dir():
        raise ValueError('Output parent does not exist')
    parent = output.parent.resolve()
    output = parent / output.name
    if seed is not None:
        seed = seed.resolve(strict=True)
        if output == seed or seed in output.parents or output in seed.parents:
            raise ValueError('Output and source cache must not overlap')
        git(seed, 'rev-parse', '--is-inside-work-tree')
        if git(seed, 'status', '--porcelain', '--untracked-files=normal'):
            raise ValueError('Seed checkout must be clean')
    tmp = Path(tempfile.mkdtemp(prefix='.' + output.name + '.api-', dir=parent))
    try:
        if seed:
            # Reuse existing Git blobs, but never alter the source cache.
            git(tmp.parent, 'clone', '-q', '--no-hardlinks', '--no-checkout', str(seed), str(tmp))
        else:
            git(tmp, 'init', '-q')
        downloaded = fetch_missing(api, repo, tmp, entries)
        git(tmp, 'read-tree', '--empty')
        index = ''.join(f"{e['mode']} {e['sha']}\t{e['path']}\n" for e in entries).encode()
        git(tmp, 'update-index', '--index-info', data=index)
        actual_tree = git(tmp, 'write-tree')
        if actual_tree != tree_sha:
            raise ValueError(f'Exact Git tree mismatch: reconstructed {actual_tree}, wanted {tree_sha}')
        if git(tmp, 'hash-object', '-t', 'commit', '-w', '--stdin', data=raw_commit) != commit_sha:
            raise ValueError('Git commit import identity mismatch')
        # Exact HEAD is a shallow boundary: full ancestral history is neither
        # available nor silently invented by the API checkout.
        shallow_path = Path(git(tmp, 'rev-parse', '--git-path', 'shallow'))
        if not shallow_path.is_absolute():
            shallow_path = tmp / shallow_path
        shallow_path.write_text(commit_sha + '\n')
        git(tmp, 'update-ref', 'refs/heads/github-api-nightly', commit_sha)
        git(tmp, 'checkout', '-q', '-f', 'github-api-nightly')
        if (git(tmp, 'rev-parse', 'HEAD') != commit_sha or
                git(tmp, 'rev-parse', 'HEAD^{tree}') != tree_sha or
                git(tmp, 'status', '--porcelain', '--untracked-files=normal')):
            raise ValueError('Final checkout identity/cleanliness verification failed')
        if len(git(tmp, 'ls-files', '-s').splitlines()) != len(entries):
            raise ValueError('Checkout index file count mismatch')
        tmp.rename(output)
    finally:
        if tmp.exists():
            shutil.rmtree(tmp)
    return {'status': 'EXACT_SOURCE_CHECKOUT', 'repo': repo, 'commit': commit_sha,
            'tree': tree_sha, 'files': len(entries), 'downloaded_missing_blobs': downloaded,
            'github_api_requests': api.read_count, 'output': str(output),
            'device_tested': False, 'firmware_built': False, 'installable': False}


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--repo', default='gobbajogger/X0X37-for-Loopy-Pro')
    parser.add_argument('--commit', required=True)
    parser.add_argument('--expected-tree')
    parser.add_argument('--verify-ref', help='ref whose current head must match --commit')
    parser.add_argument('--output', required=True, type=Path)
    parser.add_argument('--seed', type=Path, help='clean historical Git checkout as local blob cache')
    parser.add_argument('--api-base', default='https://api.github.com')
    a = parser.parse_args()
    api = API(a.api_base, os.getenv('GH_TOKEN') or os.getenv('GITHUB_TOKEN'))
    try:
        result = reconstruct(api, a.repo, a.commit, a.expected_tree, a.output, a.seed, a.verify_ref)
    except (ValueError, RuntimeError, KeyError, OSError, TypeError, json.JSONDecodeError) as e:
        print(json.dumps({'status': 'SOURCE_CHECKOUT_BLOCKED', 'reason': str(e),
                          'commit': a.commit, 'installable': False}))
        return 1
    print(json.dumps(result, sort_keys=True))
    return 0


if __name__ == '__main__':
    raise SystemExit(main())

